import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Profile & Mission","description":"Reza Bazdar (Godde3s) — creative full-stack software engineer from Iran. Web, apps, networks, industrial automation and AI infrastructure, built end-to-end.","frontmatter":{"title":"Profile & Mission","description":"Reza Bazdar (Godde3s) — creative full-stack software engineer from Iran. Web, apps, networks, industrial automation and AI infrastructure, built end-to-end."},"headers":[],"relativePath":"en/about/profile/index.md","filePath":"en/about/profile/index.md"}`),a={name:`en/about/profile/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="profile-mission" tabindex="-1">Profile &amp; Mission <a class="header-anchor" href="#profile-mission" aria-label="Permalink to “Profile &amp; Mission”">​</a></h1><p>I am <strong>Reza Bazdar</strong> — most people online know me as <strong>Godde3s</strong> or <strong>Usf</strong>. I am a creative, all-round software engineer from Iran, and I build things end-to-end: websites, applications, APIs, network infrastructure, industrial automation and AI systems. If it runs on a computer — or on a PLC next to a production line — I can build it, and I probably have.</p><p>My story is not the classic computer-science-to-big-tech pipeline. It is the story of someone who refused to accept that any system is a black box. Proxy panels, API bridges, port scanners, e-commerce sites, ladder logic — I took all of them apart, understood them, and rebuilt them better. That curiosity became a career, and the career became a toolbox that covers the entire stack.</p><h2 id="what-i-actually-do" tabindex="-1">What I actually do <a class="header-anchor" href="#what-i-actually-do" aria-label="Permalink to “What I actually do”">​</a></h2><p>On most days you will find me doing one of four things: designing and shipping full-stack web products, building networking and anti-censorship infrastructure, wiring coding agents together so they ship production software, or programming industrial controllers. The common thread is ownership — I take problems from a vague idea to something real people depend on, and I stay responsible for the result.</p><table tabindex="0"><thead><tr><th>Area</th><th>What that means in practice</th></tr></thead><tbody><tr><td>Full-Stack Web &amp; Apps</td><td>React, Vue, Next.js on the front; FastAPI, Gin, Laravel and .NET behind; databases modeled, migrated and tuned.</td></tr><tr><td>Networking &amp; Proxies</td><td>VLESS tunnels, subscription panels, edge deployments across Cloudflare, HF Spaces, Railway, Render, Fly.io and Koyeb.</td></tr><tr><td>AI &amp; Agentic Coding</td><td>OpenAI/Anthropic-compatible bridges, model routers, and daily agent-driven development with OpenCode, Codex, Claude Code and my own Hermes stack.</td></tr><tr><td>Industrial Automation</td><td>PLC programming in Ladder and Structured Text (IEC 61131-3), HMI design and SCADA logic.</td></tr></tbody></table><h2 id="why-creative-is-not-a-decoration" tabindex="-1">Why &quot;creative&quot; is not a decoration <a class="header-anchor" href="#why-creative-is-not-a-decoration" aria-label="Permalink to “Why &quot;creative&quot; is not a decoration”">​</a></h2><p>Anyone can follow a tutorial. The real work starts when the tutorial ends — when the API has no SDK, the network blocks half the internet, the hardware speaks a protocol nobody documented, and the deadline is yesterday. That is where creativity stops being a personality trait and becomes an engineering discipline: combining tools that were never meant to work together, inventing a fallback when the primary path dies, and shipping anyway.</p><div class="tip custom-block"><p class="custom-block-title">The mission</p><p>Build software that is genuinely useful, honest about what it does, and free to inspect. Everything I ship is public on <a href="https://github.com/Godde3s" target="_blank" rel="noreferrer">GitHub</a> — you can read every line of it.</p></div><h2 id="numbers-that-describe-me" tabindex="-1">Numbers that describe me <a class="header-anchor" href="#numbers-that-describe-me" aria-label="Permalink to “Numbers that describe me”">​</a></h2><ul><li><strong>9+ programming languages</strong> used in production: Python, JavaScript/TypeScript, Go, PHP, C#, C/C++, SQL, Ladder, Structured Text.</li><li><strong>30+ public repositories</strong> — API bridges, model routers, proxy panels, security tools and this very portfolio.</li><li><strong>4 languages</strong> this site speaks: English, فارسی, العربية, Español.</li><li><strong>1 rule</strong>: every project must run, not just compile.</li></ul><p>If any of that resonates — an idea, a broken system, an impossible deadline — my inbox is open. The fastest ways to reach me are Telegram and the contact details at the bottom of every page.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};